import os
from sendhog.ses import SESv2Client

client = SESv2Client(os.environ['SENDHOG_API_KEY'])

result = client.send_email(**{
    "FromEmailAddress": "sender@example.com",
    "Destination": {
        "ToAddresses": [
            "recipient@example.net"
        ]
    },
    "Content": {
        "Simple": {
            "Subject": {
                "Data": "Hello from SendHog"
            },
            "Body": {
                "Text": {
                    "Data": "Hello from your application."
                }
            }
        }
    }
})
print(result['MessageId'])

