import os
from sendhog.sendgrid import SendGridAPIClient

client = SendGridAPIClient(os.environ['SENDHOG_API_KEY'])

response = client.send({
    "from": {
        "email": "sender@example.com"
    },
    "personalizations": [
        {
            "to": [
                {
                    "email": "recipient@example.net"
                }
            ]
        }
    ],
    "subject": "Hello from SendHog",
    "content": [
        {
            "type": "text/plain",
            "value": "Hello from your application."
        }
    ]
})
print(response.headers['x-message-id'])

